<script lang="ts">
let previous = { chromatic:true, byKey:true, keyDirection:'closest', key:7, intervalUp:true, interval:0, diatonicUp:true, degree:0, keepAlterations:true, transposeKeys:true, chordNames:true, doubleAccidentals:true }
</script>
<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { prepareTransposeSelection, transposeSelection, TransposeDirection, TransposeMode } from '../../src/index'
import { qtrc, useLanguage } from '../i18n'
import { currentScore, scoreChanged } from '../scoreview'
import { closeDialog } from '../session'
useLanguage()
const score=currentScore(), info=score?prepareTransposeSelection(score):{allSelected:false,rangeSelection:false,hasChordNames:false}
if(info.allSelected)scoreChanged(false)
const state=ref({...previous,byKey:info.rangeSelection && previous.byKey}),dialog=ref<HTMLDialogElement|null>(null)
onMounted(()=>dialog.value?.showModal())
const tr=(s:string)=>qtrc('TransposeDialogBase',s)
const keys=['C♭ major / A♭ minor','G♭ major / E♭ minor','D♭ major / B♭ minor','A♭ major / F minor','E♭ major / C minor','B♭ major / G minor','F major / D minor','C major / A minor','G major / E minor','D major / B minor','A major / F♯ minor','E major / C♯ minor','B major / G♯ minor','F♯ major / D♯ minor','C♯ major / A♯ minor']
const intervals=['Perfect unison','Augmented unison','Diminished second','Minor second','Major second','Augmented second','Diminished third','Minor third','Major third','Augmented third','Diminished fourth','Perfect fourth','Augmented fourth','Diminished fifth','Perfect fifth','Augmented fifth','Diminished sixth','Minor sixth','Major sixth','Augmented sixth','Diminished seventh','Minor seventh','Major seventh','Augmented seventh','Diminished octave','Perfect octave']
const degrees=['Second','Third','Fourth','Fifth','Sixth','Seventh']
function apply(){if(!score)return;const s=state.value,mode=s.chromatic?(s.byKey?TransposeMode.TO_KEY:TransposeMode.BY_INTERVAL):TransposeMode.DIATONICALLY,direction=mode===TransposeMode.TO_KEY?(s.keyDirection==='closest'?TransposeDirection.CLOSEST:s.keyDirection==='up'?TransposeDirection.UP:TransposeDirection.DOWN):(s.chromatic?s.intervalUp:s.diatonicUp)?TransposeDirection.UP:TransposeDirection.DOWN;previous={...s};transposeSelection(score,{mode,direction,key:s.key-7,interval:s.chromatic?s.interval:s.degree+1,needTransposeKeys:s.chromatic?s.transposeKeys:s.keepAlterations,needTransposeChordNames:s.chordNames,needTransposeDoubleSharpsFlats:s.doubleAccidentals},info.allSelected);scoreChanged();dialog.value?.close()}
</script>
<template><dialog ref="dialog" class="transpose" aria-labelledby="transpose-title" @close="closeDialog()"><h2 id="transpose-title">{{tr('Transpose')}}</h2><form @submit.prevent="apply">
 <fieldset class="groupbox" :disabled="!state.chromatic"><legend><label class="check"><input v-model="state.chromatic" type="radio" name="transpose-kind" :value="true" />{{tr('Transpose chromatically')}}</label></legend>
  <fieldset class="groupbox" :disabled="!info.rangeSelection || !state.byKey" :title="tr('Transpose to key (specified at concert pitch)')"><legend><label class="check"><input v-model="state.byKey" type="radio" name="transpose-chromatic" :value="true" :disabled="!info.rangeSelection" />{{tr('To Key')}}</label></legend><div class="groupbox-row"><select v-model.number="state.key"><option v-for="(key,i) in keys" :key="key" :value="i">{{tr(key)}}</option></select><div class="radio-rows"><label v-for="direction in ['closest','up','down']" :key="direction" class="check"><input v-model="state.keyDirection" type="radio" name="transpose-key-direction" :value="direction" />{{tr(direction==='closest'?'Closest':direction==='up'?'Up':'Down')}}</label></div></div></fieldset>
  <fieldset class="groupbox" :disabled="state.byKey" :title="tr('Transpose by interval')"><legend><label class="check"><input v-model="state.byKey" type="radio" name="transpose-chromatic" :value="false" />{{tr('By interval')}}</label></legend><div class="groupbox-row"><select v-model.number="state.interval" :aria-label="tr('Interval type')"><option v-for="(interval,i) in intervals" :key="interval" :value="i">{{tr(interval)}}</option></select><div class="radio-rows"><label class="check"><input v-model="state.intervalUp" type="radio" name="transpose-interval-direction" :value="true" />{{tr('Up')}}</label><label class="check"><input v-model="state.intervalUp" type="radio" name="transpose-interval-direction" :value="false" />{{tr('Down')}}</label></div></div></fieldset><label class="check"><input v-model="state.transposeKeys" type="checkbox" :disabled="!info.rangeSelection" />{{tr('Transpose key signatures')}}</label>
 </fieldset>
 <fieldset class="groupbox" :disabled="state.chromatic"><legend><label class="check"><input v-model="state.chromatic" type="radio" name="transpose-kind" :value="false" />{{tr('Transpose diatonically')}}</label></legend><div class="groupbox-row"><select v-model.number="state.degree" :aria-label="tr('Degree type')"><option v-for="(degree,i) in degrees" :key="degree" :value="i">{{tr(degree)}}</option></select><div class="radio-rows"><label class="check"><input v-model="state.diatonicUp" type="radio" name="transpose-diatonic-direction" :value="true" />{{tr('Up')}}</label><label class="check"><input v-model="state.diatonicUp" type="radio" name="transpose-diatonic-direction" :value="false" />{{tr('Down')}}</label></div></div><label class="check"><input v-model="state.keepAlterations" type="checkbox" />{{tr('Keep degree alterations')}}</label></fieldset>
 <fieldset class="groupbox"><legend>{{tr('Options')}}</legend><label class="check"><input v-model="state.chordNames" type="checkbox" :disabled="!info.hasChordNames" />{{tr('Transpose chord symbols and fretboard diagrams')}}</label><label class="groupbox-row"><span>{{tr('Accidentals:')}}</span><select v-model="state.doubleAccidentals"><option :value="false">{{tr('Single ♯ and ♭ only')}}</option><option :value="true">{{tr('Use double ♯ and ♭')}}</option></select></label></fieldset><div class="dialog-buttons"><button type="button" class="secondary" @click="dialog?.close()">{{qtrc('global','Cancel')}}</button><button type="submit" class="primary" autofocus>{{qtrc('global','OK')}}</button></div></form></dialog></template>
